from __future__ import annotations
import math
import random
import itertools
from typing import List, Tuple
import numpy as np
try:
    from scipy.optimize import minimize
except ImportError:
    minimize = None

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    for i, j, k in itertools.combinations(range(len(pts)), 3):
        a = _area(pts[i], pts[j], pts[k])
        if a < best:
            best = a
            if best == 0:
                return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_points(n: int) -> np.ndarray:
    points = []
    size = int(math.ceil(math.sqrt(n)))
    for i in range(size):
        for j in range(size):
            if len(points) >= n:
                break
            x = (i + 0.5 * (j % 2)) / (size - 0.5)
            y = (j * SQRT3 / 2) / (size - 0.5)
            if y > SQRT3/2 or x > 1 or (x > 0.5 and y > (-SQRT3*(x-1))):
                continue
            points.append([x, y])
    return np.array(points[:n])

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        u, v = u/(u+v), v/(u+v)
    return (1 - u - v) * _A + u * _B + v * _C

def _optimize(pts: np.ndarray, iters: int = 50000, temp: float = 0.1) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    current_pts = pts.copy()

    for t in range(iters):
        T = temp * (1 - t/iters)
        idx = random.randrange(len(pts))
        step = 0.05 * (1 - t/iters)

        trial = current_pts.copy()
        trial[idx] += np.random.normal(0, step, 2)
        trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or (T > 0 and random.random() < math.exp(delta/T)):
            current_pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

    return best_pts

def _local_optimize(pts: np.ndarray) -> np.ndarray:
    if minimize is None:
        return pts
    x0 = pts.ravel()
    def f(x):
        P = x.reshape((-1, 2))
        return -_min_triangle_area(P)
    res = minimize(f, x0, method='Nelder-Mead', 
                  options={'maxiter': 10000, 'adaptive': True})
    if res.success:
        out = res.x.reshape((-1, 2))
        for i in range(len(out)):
            out[i] = _project_to_simplex(out[i])
        return out
    return pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    random.seed(seed)
    np.random.seed(seed)

    best_score = 0
    best_pts = None

    for _ in range(5):
        if random.random() < 0.7:
            pts = _hexagonal_points(11)
        else:
            pts = np.array([_project_to_simplex(np.random.rand(2)) for _ in range(11)])

        pts = _optimize(pts, iters=50000, temp=0.1)
        pts = _local_optimize(pts)

        score = _min_triangle_area(pts)
        if score > best_score:
            best_score = score
            best_pts = pts

    return [(float(x), float(y)) for x, y in best_pts]

import math
import numpy as np
from scipy.optimize import differential_evolution
from itertools import combinations

SQRT3 = math.sqrt(3.0)

def _area(p, q, r):
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts):
    min_area = float('inf')
    for trio in combinations(pts, 3):
        a = _area(*trio)
        if a < min_area:
            min_area = a
            if min_area == 0:
                return 0
    return min_area

def _hexagonal_grid(n):
    pts = []
    size = int(math.sqrt(n * 2 / SQRT3)) + 1
    for i in range(size):
        for j in range(size - i):
            x = (i + 0.5 * j) / size
            y = SQRT3 * j / (2 * size)
            if x <= 1 and y <= SQRT3/2 and (1 - x) * SQRT3 >= y:
                pts.append([x, y])
    return np.array(pts[:n])

def _constraint(x):
    pts = x.reshape(-1, 2)
    A = np.array([0.0, 0.0])
    B = np.array([1.0, 0.0])
    C = np.array([0.5, SQRT3/2])
    M = np.column_stack((B - A, C - A))
    uv = np.linalg.lstsq(M, pts - A, rcond=None)[0].T
    return np.minimum(uv[:,0], np.minimum(uv[:,1], 1 - uv[:,0] - uv[:,1]))

def optimize_points():
    n = 11
    bounds = [(0,1), (0,SQRT3/2)] * n

    def objective(x):
        pts = x.reshape(-1, 2)
        return -_min_triangle_area(pts)

    constraints = {'type': 'ineq', 'fun': _constraint}

    init_pts = _hexagonal_grid(n)
    init_x = init_pts.flatten()

    result = differential_evolution(
        objective,
        bounds,
        strategy='best1bin',
        maxiter=1000,
        popsize=20,
        mutation=(0.5, 1.0),
        recombination=0.7,
        constraints=constraints,
        polish=True,
        init=np.array([init_x])
    )

    return result.x.reshape(-1, 2)

def find_points(seed=None):
    np.random.seed(seed)
    pts = optimize_points()
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

