import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    for i, j, k in itertools.combinations(range(len(pts)), 3):
        a = _area(pts[i], pts[j], pts[k])
        if a < best:
            best = a
            if best == 0:
                return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_lattice_points(n_pts: int = 11) -> np.ndarray:
    pts = []
    layers = 0
    while len(pts) < n_pts:
        layers += 1
        pts = []
        for i in range(layers + 1):
            for j in range(layers + 1 - i):
                u = i / layers
                v = j / layers
                pts.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(pts[:n_pts])

def _local_optimization(pts: np.ndarray, max_iter: int = 1000) -> np.ndarray:
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    n = len(pts)
    step = 0.01

    for _ in range(max_iter):
        improved = False
        for i in range(n):
            for dx, dy in [(step, 0), (-step, 0), (0, step), (0, -step)]:
                trial = best_pts.copy()
                trial[i] += np.array([dx, dy])
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()
                    improved = True
        if not improved:
            step *= 0.5
            if step < 1e-6:
                break
    return best_pts

def _parallel_tempering(n_pts: int = 11, chains: int = 4, iters: int = 5000) -> np.ndarray:
    temps = [0.1 * (1.5 ** i) for i in range(chains)]
    populations = [_hexagonal_lattice_points(n_pts) for _ in range(chains)]
    best_pts = populations[0].copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        for c in range(chains):
            T = temps[c]
            step_size = 0.05 * (1 - (t/iters)**0.5) + 0.001
            idx = random.randrange(n_pts)
            trial = populations[c].copy()
            if random.random() < 0.05:
                trial[idx] = _random_point()
            else:
                trial[idx] += random.uniform(-step_size, step_size), random.uniform(-step_size, step_size)
                trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - _min_triangle_area(populations[c])

            if delta > 0 or random.random() < math.exp(delta / max(T, 1e-12)):
                populations[c] = trial
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

        if t % 100 == 0 and chains > 1:
            i, j = random.sample(range(chains), 2)
            val_i = _min_triangle_area(populations[i])
            val_j = _min_triangle_area(populations[j])
            delta = (val_i - val_j) * (1/temps[i] - 1/temps[j])
            if delta < 0 or random.random() < math.exp(-delta):
                populations[i], populations[j] = populations[j], populations[i]

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    if seed is not None:
        random.seed(seed)
        np.random.seed(seed)
    pts = _parallel_tempering(n_pts=11, chains=4, iters=5000)
    pts = _local_optimization(pts, max_iter=1000)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

