import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    best = float("inf")
    # Use spatial partitioning to reduce checks
    grid = {}
    for i, p in enumerate(pts):
        x, y = int(p[0]*10), int(p[1]*10)
        if (x,y) not in grid:
            grid[(x,y)] = []
        grid[(x,y)].append(i)

    for (x1,y1), indices1 in grid.items():
        for (x2,y2), indices2 in grid.items():
            if x2 < x1 or (x2 == x1 and y2 < y1):
                continue
            for (x3,y3), indices3 in grid.items():
                if x3 < x2 or (x3 == x2 and y3 < y2):
                    continue
                for i in indices1:
                    for j in indices2:
                        if j == i:
                            continue
                        for k in indices3:
                            if k == i or k == j:
                                continue
                            a = _area(pts[i], pts[j], pts[k])
                            if a < best:
                                best = a
                                if best == 0:
                                    return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _hexagonal_points(n: int) -> List[np.ndarray]:
    pts = []
    layers = math.ceil(math.sqrt(n / 3)) + 1
    for i in range(-layers, layers+1):
        for j in range(-layers, layers+1):
            x = 0.5 + 0.5*i + 0.25*j
            y = SQRT3/4 * j
            if x >= 0 and y >= 0 and (1 - x - y/SQRT3*2) >= 0:
                pts.append(np.array([x, y]))
    return pts

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = _hexagonal_points(n_pts)
    if len(pts) > n_pts:
        pts = random.sample(pts, n_pts)
    while len(pts) < n_pts:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            pts.append((1 - u - v) * _A + u * _B + v * _C)
    return np.array(pts)

def _gradient_step(pts: np.ndarray, idx: int) -> np.ndarray:
    current = pts[idx]
    best_move = np.zeros(2)
    best_improvement = 0

    for _ in range(10):
        direction = np.random.normal(size=2)
        direction /= np.linalg.norm(direction)
        for step in [0.01, 0.02, 0.05]:
            trial = current + step * direction
            trial = _project_to_simplex(trial)
            pts_copy = pts.copy()
            pts_copy[idx] = trial
            new_area = _min_triangle_area(pts_copy)
            current_area = _min_triangle_area(pts)
            improvement = new_area - current_area
            if improvement > best_improvement:
                best_improvement = improvement
                best_move = step * direction

    return current + best_move

def _anneal(n_pts: int = 11,
            iters: int = 5000,
            start_temp: float = 0.1,
            end_temp: float = 1e-8,
            seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    pts = _initial_configuration(n_pts)
    best_pts = pts.copy()
    best_val = _min_triangle_area(best_pts)
    no_improve = 0

    for t in range(iters):
        if no_improve > 500:
            break

        T = start_temp * (end_temp / start_temp) ** (t / (iters - 1))
        step_size = 0.05 * (1 - (t/iters)**0.5) + 0.001

        idx = rng.randrange(n_pts)
        trial = pts.copy()

        if rng.random() < 0.3:  # gradient-based move
            trial[idx] = _gradient_step(pts, idx)
        elif rng.random() < 0.1:  # large jump
            trial[idx] = _project_to_simplex(_random_point())
        else:  # random move
            trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
            trial[idx] = _project_to_simplex(trial[idx])

        trial_val = _min_triangle_area(trial)
        delta = trial_val - best_val

        if delta > 0 or rng.random() < math.exp(delta / max(T, 1e-12)):
            pts = trial
            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()
                no_improve = 0
            else:
                no_improve += 1

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _anneal(n_pts=11, iters=5000, seed=seed)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]

