import math
import random
import itertools
from typing import List, Tuple
import numpy as np

SQRT3 = math.sqrt(3.0)

def _area(p: np.ndarray, q: np.ndarray, r: np.ndarray) -> float:
    return abs(np.cross(q - p, r - p)) * 0.5

def _min_triangle_area(pts: np.ndarray) -> float:
    n = len(pts)
    best = float("inf")
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                a = _area(pts[i], pts[j], pts[k])
                if a < best:
                    best = a
                    if best == 0:
                        return 0
    return best

_A = np.array([0.0, 0.0])
_B = np.array([1.0, 0.0])
_C = np.array([0.5, SQRT3 / 2.0])

def _random_point() -> np.ndarray:
    while True:
        u, v = random.random(), random.random()
        if u + v <= 1.0:
            break
    return (1 - u - v) * _A + u * _B + v * _C

def _project_to_simplex(p: np.ndarray) -> np.ndarray:
    M = np.column_stack((_B - _A, _C - _A))
    uv = np.linalg.lstsq(M, p - _A, rcond=None)[0]
    u, v = uv
    w = 1.0 - u - v
    if u >= 0 and v >= 0 and w >= 0:
        return p
    u = max(0.0, min(1.0, u))
    v = max(0.0, min(1.0, v))
    if u + v > 1.0:
        s = u + v
        u /= s
        v /= s
    return (1 - u - v) * _A + u * _B + v * _C

def _hexagonal_points(n: int) -> List[np.ndarray]:
    points = []
    layers = math.ceil((math.sqrt(4 * n / math.sqrt(3) - 1) / 2) + 1
    for i in range(-layers, layers + 1):
        for j in range(-layers, layers + 1):
            x = 0.5 + i * 0.5 + j * 0.5
            y = SQRT3 / 2 * (i - j)
            if x >= 0 and x <= 1 and y >= 0 and y <= SQRT3 / 2:
                points.append(np.array([x, y]))
    if len(points) > n:
        points = random.sample(points, n)
    return points

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = _hexagonal_points(n_pts)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _parallel_anneal(n_pts: int = 11, iters: int = 5000, chains: int = 5, seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    chains_pts = [_initial_configuration(n_pts) for _ in range(chains)]
    chains_vals = [_min_triangle_area(pts) for pts in chains_pts]
    best_pts = chains_pts[np.argmax(chains_vals)].copy()
    best_val = max(chains_vals)

    temps = np.geomspace(0.2, 1e-8, chains)

    for t in range(iters):
        step_size = 0.05 * (1 - (t/iters)**0.5) + 0.001

        for c in range(chains):
            idx = rng.randrange(n_pts)
            trial = chains_pts[c].copy()
            if rng.random() < 0.05:
                trial[idx] = _random_point()
            else:
                trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
                trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - chains_vals[c]

