    return (1 - u - v) * _A + u * _B + v * _C

def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    pts.extend([_A, _B, _C])
    pts.append((_A + _B) / 2)
    pts.append((_A + _C) / 2)
    pts.append((_B + _C) / 2)
    pts.append((_A + _B + _C) / 3)
    pts.append((_A + _A + _B + _C) / 4)
    pts.append((_B + _A + _B + _C) / 4)
    pts.append((_C + _A + _B + _C) / 4)
    while len(pts) < n_pts:
        pts.append(_random_point())
    return np.array(pts)

def _local_optimize(pts: np.ndarray, best_val: float) -> Tuple[np.ndarray, float]:
    for _ in range(5):
        for i in range(len(pts)):
            neighbors = []
            for j in range(len(pts)):
                if i != j:
                    neighbors.append(np.linalg.norm(pts[i] - pts[j]))
            if neighbors:
                min_dist = min(neighbors)
                move_dir = np.zeros(2)
                for j in range(len(pts)):
                    if i != j:
                        diff = pts[i] - pts[j]
                        dist = np.linalg.norm(diff)
                        if dist < 2 * min_dist:
                            move_dir += diff / (dist**3)
                if np.linalg.norm(move_dir) > 1e-6:
                    trial = pts.copy()
                    trial[i] = _project_to_simplex(trial[i] + 0.1 * min_dist * move_dir / np.linalg.norm(move_dir))
                    trial_val = _min_triangle_area(trial)
                    if trial_val > best_val:
                        pts = trial
                        best_val = trial_val
    return pts, best_val

