            if trial_val > best_val:
                best_val = trial_val
                best_pts = trial.copy()

        if t % 100 == 0:
            pts, best_val = _local_optimize(pts, best_val)
            best_pts = pts.copy() if best_val == _min_triangle_area(pts) else best_pts

    return best_pts

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
