def _initial_configuration(n_pts: int = 11) -> np.ndarray:
    pts = []
    pts.extend([_A, _B, _C])

    # Add points in hexagonal pattern
    layers = 2
    for i in range(layers):
        for j in range(layers):
            if i + j < layers:
                u = (i + 0.5 * j) / layers
                v = (j * SQRT3 / 2) / layers
                if u + v <= 1.0:
                    pts.append((1 - u - v) * _A + u * _B + v * _C)

    # Fill remaining with optimized points
    while len(pts) < n_pts:
        best_p = None
        best_min_area = -1
        for _ in range(10):
            p = _random_point()
            trial_pts = np.array(pts + [p])
            min_area = _min_triangle_area(trial_pts)
            if min_area > best_min_area:
                best_min_area = min_area
                best_p = p
        pts.append(best_p)

