def _parallel_tempering(n_pts: int = 11,
                       chains: int = 5,
                       iters: int = 2000,
                       seed: int | None = 0) -> np.ndarray:
    rng = random.Random(seed)
    temps = [0.2 * (0.1 ** (i/(chains-1))) for i in range(chains)]
    configs = [_initial_configuration(n_pts) for _ in range(chains)]
    best_pts = configs[0].copy()
    best_val = _min_triangle_area(best_pts)

    for t in range(iters):
        step_size = 0.1 * (1 - t/iters) + 0.01

        for c in range(chains):
            idx = rng.randrange(n_pts)
            trial = configs[c].copy()
            if rng.random() < 0.05:
                trial[idx] = _random_point()
            else:
                trial[idx] += rng.uniform(-step_size, step_size), rng.uniform(-step_size, step_size)
                trial[idx] = _project_to_simplex(trial[idx])

            trial_val = _min_triangle_area(trial)
            delta = trial_val - _min_triangle_area(configs[c])

            if delta > 0 or rng.random() < math.exp(delta / max(temps[c], 1e-12)):
                configs[c] = trial
                if trial_val > best_val:
                    best_val = trial_val
                    best_pts = trial.copy()

        if t % 10 == 0 and chains > 1:
            i, j = rng.sample(range(chains), 2)
            delta = (_min_triangle_area(configs[i]) - _min_triangle_area(configs[j])) * (1/temps[j] - 1/temps[i])
            if delta > 0 or rng.random() < math.exp(delta):
                configs[i], configs[j] = configs[j].copy(), configs[i].copy()

