    n = len(pts)
    current = pts.copy()
    best = pts.copy()
    best_val = _min_triangle_area(best)

    for _ in range(steps):
        improved = False
        for i in range(n):
            for dx, dy in [(0.01, 0), (-0.01, 0), (0, 0.01), (0, -0.01)]:
                trial = current.copy()
                trial[i] += dx, dy
                trial[i] = _project_to_simplex(trial[i])
                trial_val = _min_triangle_area(trial)
                if trial_val > best_val:
                    best_val = trial_val
                    best = trial.copy()
                    improved = True
        if not improved:
            break
        current = best.copy()
    return best

def find_points(seed: int | None = 0) -> List[Tuple[float, float]]:
    pts = _parallel_tempering(n_pts=11, iters=2000, seed=seed)
    pts = _local_optimize(pts)
    return [(float(f"{x:.8f}"), float(f"{y:.8f}")) for x, y in pts]
